package ec.espe.facturacion.adapters.in;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.core.type.TypeReference; import com.sun.net.httpserver.*; import ec.espe.facturacion.application.CreateInvoiceCommand; import ec.espe.facturacion.domain.*; import java.io.*; import java.net.InetSocketAddress; import java.math.BigDecimal; import java.util.*;
public class RestAdapter {
 private final ObjectMapper json=new ObjectMapper().findAndRegisterModules(); private final InvoiceService service;
 public RestAdapter(InvoiceService s){service=s;}
 public void start(int port)throws IOException { HttpServer server=HttpServer.create(new InetSocketAddress(port),0); server.createContext("/invoices",x->{try{x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8"); if(!x.getRequestMethod().equals("POST")){reply(x,405,Map.of("error","Use POST"));return;} Map<String,Object> m=json.readValue(x.getRequestBody(),new TypeReference<>(){}); var lines=new ArrayList<InvoiceLine>(); for(var raw:(List<Map<String,Object>>)m.getOrDefault("lines",List.of())) lines.add(new InvoiceLine((String)raw.get("description"),((Number)raw.get("quantity")).intValue(),new BigDecimal(raw.get("unitPrice").toString()))); var result=service.create(new CreateInvoiceCommand((String)m.get("operationId"),(String)m.get("customerId"),lines)); reply(x,201,result); }catch(BusinessRuleException|IllegalArgumentException e){reply(x,422,Map.of("error",e.getMessage()));}catch(Exception e){reply(x,500,Map.of("error","Error interno"));}}); server.setExecutor(java.util.concurrent.Executors.newCachedThreadPool()); server.start(); System.out.println("REST escuchando en http://localhost:"+port+"/invoices"); }
 private void reply(HttpExchange x,int code,Object body)throws IOException{byte[] b=json.writeValueAsBytes(body);x.sendResponseHeaders(code,b.length);try(var o=x.getResponseBody()){o.write(b);}}
}